import { Novu } from '@novu/node';

const novu = new Novu(process.env.NOVU_API_KEY!);

// Identify subscriber (creates if not exists)
await novu.subscribers.identify('user-123', {
  firstName: 'Jane',
  lastName: 'Smith',
  email: 'jane@example.com',
  phone: '+14155551234',
});

// Trigger workflow
const result = await novu.trigger('order-shipped', {
  to: { subscriberId: 'user-123' },
  payload: {
    orderId: 'order_456',
    trackingUrl: 'https://track.example.com/order_456',
    estimatedDelivery: 'Feb 28, 2026',
  },
});

console.log('Triggered:', result.data?.transactionId);
